  vpc_id                  = aws_vpc.goat_vpc.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true
  tags = {
    Name = "AWS_GOAT App subnet"
  }
}

resource "aws_route_table" "goat_rt" {
  vpc_id = aws_vpc.goat_vpc.id
