  route_table_id = aws_route_table.goat_rt.id
}

resource "aws_security_group" "goat_sg" {
  name        = "AWS_GOAT_sg"
  description = "AWS_GOAT_sg"
  vpc_id      = aws_vpc.goat_vpc.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AWS_GOAT_sg"
  }
}


